import React, { useState, useEffect } from 'react'
import { Link, useNavigate } from 'react-router-dom'

function Mycourses() {
  const [enrolledCourses, setEnrolledCourses] = useState([])
  const navigate = useNavigate()
  const isLoggedIn = localStorage.getItem('isLoggedIn') === 'true'

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem('enrolledCourses')) || []
    setEnrolledCourses(saved)
  }, [])

  const handleStartLearning = (id) => {
    if (!isLoggedIn) {
      alert('Please login first to start learning!')
      navigate('/Login')
    } else {
      navigate(`/Player/${id}`)
    }
  }

  const handleUnenroll = (id) => {
    const updated = enrolledCourses.filter(c => c.id !== id)
    localStorage.setItem('enrolledCourses', JSON.stringify(updated))
    setEnrolledCourses(updated)
  }

  return (
    <div style={{ backgroundColor: '#81A6C6', minHeight: '100vh', padding: '30px 0' }}>
      <h1 style={{ color: '#F3E3D0', textAlign: 'center', fontSize: '32px', marginBottom: '30px', fontWeight: 'bold' }}>
        My Courses
      </h1>
      <div className="container">
        {enrolledCourses.length === 0 ? (
          <div className="text-center mt-5">
            <p style={{ color: '#F3E3D0', fontSize: '18px' }}>You have not enrolled in any courses yet.</p>
            <Link
              to="/"
              className="btn mt-3"
              style={{ backgroundColor: '#F3E3D0', color: '#81A6C6', borderRadius: '8px', fontWeight: 'bold' }}
            >
              Browse Courses
            </Link>
          </div>
        ) : (
          <div className="row g-4">
            {enrolledCourses.map(course => (
              <div className="col-md-3" key={course.id}>
                <div className="card h-100 course-card" style={{ backgroundColor: '#F3E3D0', border: 'none', borderRadius: '12px' }}>
                  <img
                    src={course.image}
                    className="card-img-top p-3"
                    alt={course.title}
                    style={{ height: '180px', objectFit: 'contain' }}
                  />
                  <div className="card-body d-flex flex-column justify-content-between">
                    <h5 className="card-title text-center" style={{ color: '#81A6C6', fontSize: '16px', fontWeight: 'bold' }}>
                      {course.title}
                    </h5>
                    <button
                      className="btn mb-2"
                      onClick={() => handleStartLearning(course.id)}
                      style={{ backgroundColor: '#81A6C6', color: '#ffffff', borderRadius: '8px', fontWeight: 'bold' }}
                    >
                      Start Learning
                    </button>
                    <button
                      className="btn"
                      onClick={() => handleUnenroll(course.id)}
                      style={{ backgroundColor: '#D2C4B4', color: '#ffffff', borderRadius: '8px', fontWeight: 'bold' }}
                    >
                      Unenroll
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

export default Mycourses
